#include <stdio.h>
#include <string.h>

int append(char *dst, size_t size, const char *src) {
    size_t used = strlen(dst);
    size_t extra = strlen(src);
    if (used + extra + 1 > size) {
        return -1;
    }
    memcpy(dst + used, src, extra + 1);
    return 0;
}

int main(void) {
    char path[32] = "";
    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        char part[64];
        scanf("%63s", part);
        if (append(path, sizeof path, part) == 0) {
            printf("ok %s\n", path);
        } else {
            printf("overflow %s\n", path);
        }
    }
    return 0;
}

