#include <stdio.h>

int main(void) {
    int w, n;
    scanf("%d %d", &w, &n);
    for (int i = 0; i < n; i++) {
        char name[41];
        int id;
        scanf("%40s %d", name, &id);
        char label[31];
        int needed = snprintf(label, (size_t)w + 1, "%s#%d", name, id);
        if (needed > w) {
            printf("%s * (%d)\n", label, needed);
        } else {
            printf("%s\n", label);
        }
    }
    return 0;
}

